@Bean
RestClient shippingClient(RestClient.Builder builder) {
    HttpClient http = HttpClient.newBuilder()
        .connectTimeout(Duration.ofSeconds(1))          // opening the connection
        .build();
    JdkClientHttpRequestFactory factory = new JdkClientHttpRequestFactory(http);
    factory.setReadTimeout(Duration.ofSeconds(3));      // waiting for the response
    return builder
        .baseUrl("http://api-shipping")
        .requestFactory(factory)
        .build();
}

